    pprs = p.getElementsByTagName("w:pPr")
    if not pprs:
        return ""
    styles = pprs[0].getElementsByTagName("w:pStyle")
    if not styles:
        return ""
    return styles[0].getAttribute("w:val") or ""


def is_headline(style):
    return bool(style) and (style in HEADLINE_STYLES or style.startswith(HEADLINE_STYLES))


def para_text(p):
    return "".join(
        t.firstChild.nodeValue
        for t in p.getElementsByTagName("w:t")
        if t.firstChild and t.firstChild.nodeValue
    )


def inside_deletion(run, para):
    node = run.parentNode
    while node is not None and node is not para:
        if node.nodeType == node.ELEMENT_NODE and node.tagName == "w:del":
            return True
        node = node.parentNode
    return False


def ensure_underline(rpr, dom):
    if rpr.getElementsByTagName("w:u"):
        return False
    u = dom.createElement("w:u")
    u.setAttribute("w:val", "single")
    kids = [c for c in rpr.childNodes if c.nodeType == c.ELEMENT_NODE]
