))


def para_text(p):
    return "".join(
        t.firstChild.data
        for t in p.getElementsByTagName("w:t")
        if t.firstChild is not None
    )


def is_headline(text):
    s = text.strip()
    if not s:
        return False
    return any(ch.isalpha() for ch in s) and s == s.upper()


