                    break
            if anchor is not None:
                rpr.insertBefore(u, anchor.nextSibling)
            else:
                rpr.insertBefore(u, rpr.firstChild)
            changed += 1

    if flagged == 0 or changed == 0:
        raise RuntimeError("no headlines processed")

    with open(DOCXML, "wb") as fh:
        fh.write(dom.toxml(encoding="utf-8"))

