        flagged += 1
        for r in p.getElementsByTagName("w:r"):
            rprs = r.getElementsByTagName("w:rPr")
            rpr = rprs[0] if rprs else None
            if rpr is None:
                rpr = dom.createElementNS(W_NS, "w:rPr")
                r.insertBefore(rpr, r.firstChild)
            if rpr.getElementsByTagName("w:u"):
                continue
            u = dom.createElementNS(W_NS, "w:u")
            u.setAttribute("w:val", "single")
            anchor = None
            for c in rpr.childNodes:
                if c.nodeType != c.ELEMENT_NODE:
                    continue
                if c.tagName in BEFORE_U:
                    anchor = c
                else:
                    break
            if anchor is not None:
                rpr.insertBefore(u, anchor.nextSibling)
            else:
                rpr.insertBefore(u, rpr.firstChild)
            changed += 1

    if flagged == 0 or changed == 0:
        raise RuntimeError("no headlines processed")

    with open(DOCXML, "wb") as fh:
        fh.write(dom.toxml(encoding="utf-8"))

    # Verification pass: re-read the saved part and confirm each headline
    # run now carries an underline property while paragraph text is intact.
    dom2 = parse(DOCXML)
    underlined = 0
    for p in dom2.getElementsByTagName("w:p"):
        if not is_headline(para_text(p)):
            continue
        runs = p.getElementsByTagName("w:r")
        if runs and all(r.getElementsByTagName("w:u") for r in runs):
            underlined += 1
    print("Headline paragraphs flagged:", flagged)
    print("Headline paragraphs verified underlined:", underlined)
    print("Underline run properties added:", changed)


if __name__ == "__main__":
    main()
